txs = cells('W0::Transactions', 'L42:N47')
rates = cells('W0::Effective rates', 'C804:F807')

total_usd = 0.0
for curr, amt, dt in txs:
    if isinstance(dt, str):
        dt_obj = datetime.datetime.fromisoformat(dt)
    else:
        dt_obj = dt

    rate = None
    for end_c, r_val, r_curr, start_c in rates:
        if r_curr == curr:
            s_dt = start_c if isinstance(start_c, datetime.datetime) else datetime.datetime.fromisoformat(start_c)
            e_dt = end_c if isinstance(end_c, datetime.datetime) else datetime.datetime.fromisoformat(end_c)
            if s_dt <= dt_obj < e_dt:
                rate = r_val
                break
    total_usd += amt * rate
result = round(total_usd, 2)

cost_map = dict(zip(values('W1::Providers', 'D42:D47'), values('W1::Providers', 'C42:C47')))
coverage = {}
for p, a in zip(values('W1::Coverage', 'C804:C813'), values('W1::Coverage', 'D804:D813')):
    coverage.setdefault(p, set()).add(a)
required = set(values('W1::Required', 'C42:C45'))
providers = list(cost_map.keys())
min_cost = 999999
from itertools import combinations
for r in range(1, len(providers) + 1):
    for combo in combinations(providers, r):
        covered = set()
        c_sum = 0
        for p in combo:
            covered.update(coverage.get(p, set()))
            c_sum += cost_map[p]
        if required.issubset(covered):
            if c_sum < min_cost:
                min_cost = c_sum
result = min_cost

